import { Button } from "@/registry/erbium/ui/button";
import {
  Dialog,
  DialogClose,
  DialogPanel,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogContent,
  DialogTitle,
  DialogTrigger,
} from "@/registry/erbium/ui/dialog";
import { Input } from "@/registry/erbium/ui/input";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";

export default function DialogCloseButton() {
  return (
    <Dialog>
      <DialogTrigger render={<Button variant="outline">Share</Button>} />
      <DialogPanel className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Share link</DialogTitle>
          <DialogDescription>Anyone who has this link will be able to view this.</DialogDescription>
        </DialogHeader>
        <DialogContent className="flex items-center gap-related">
          <Field className="flex-1">
            <FieldLabel className="sr-only">Link</FieldLabel>
            <Input defaultValue="https://ui.erbium.app/docs/installation" readOnly />
          </Field>
        </DialogContent>
        <DialogFooter className="sm:justify-start">
          <DialogClose
            render={
              <Button type="button" variant="secondary">
                Close
              </Button>
            }
          />
        </DialogFooter>
      </DialogPanel>
    </Dialog>
  );
}

import ExampleDialogCloseButton from "../examples/dialog-close-button";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleDialogCloseButton />
  </div>
);

export default Example;
